// WF-11: structured leave request. Body: { email, leave_type, start_date, end_date, reason }
const b = $json.body || $json;
const email = String(b.email || '').toLowerCase().trim();
const type = String(b.leave_type || '').toUpperCase().trim();
const start = String(b.start_date || '').trim();
const end = String(b.end_date || start).trim();
const reason = b.reason || '';
const valid = ['ANNUAL','SICK','FAMILY','STUDY','OTHER'];
const dateRe = /^\d{4}-\d{2}-\d{2}$/;

let err = null;
if (!email) err = 'email is required';
else if (!valid.includes(type)) err = 'leave_type must be one of ' + valid.join(', ');
else if (!dateRe.test(start)) err = 'start_date must be YYYY-MM-DD';
else if (!dateRe.test(end)) err = 'end_date must be YYYY-MM-DD';
else if (end < start) err = 'end_date cannot be before start_date';

let sql, params;
if (err) { sql = `SELECT 'ERR' AS err`; params = []; }
else {
  sql = `WITH u AS (SELECT user_id, mentor_id FROM users WHERE email=$1),
ins AS (
  INSERT INTO leave_requests (user_id, leave_type, start_date, end_date, reason, status)
  SELECT user_id, $2, $3::date, $4::date, $5, 'SUBMITTED' FROM u
  RETURNING leave_id, leave_type, start_date, end_date
),
notif AS (
  INSERT INTO notifications (user_id, type, message)
  SELECT u.mentor_id, 'LEAVE_REQUEST',
    'Leave (' || ins.leave_type || ') from ' || $1 || ' ' || to_char(ins.start_date,'YYYY-MM-DD') || ' to ' || to_char(ins.end_date,'YYYY-MM-DD')
  FROM ins, u WHERE u.mentor_id IS NOT NULL
  RETURNING 1
)
SELECT ins.leave_type, to_char(ins.start_date,'YYYY-MM-DD') AS start_date, to_char(ins.end_date,'YYYY-MM-DD') AS end_date FROM ins`;
  params = [email, type, start, end, reason];
}
return [{ json: { err, email, type, sql, params } }];

const built = $('Build Leave').first().json;
const d = $json || {};
let reply;
if (built.err) reply = '\u26a0\ufe0f ' + built.err;
else if (!d.leave_type) reply = `\u26a0\ufe0f Could not create leave (user not found: ${built.email}).`;
else reply = `\ud83d\udcc4 ${d.leave_type} leave requested for ${d.start_date} \u2192 ${d.end_date}. Sent to your mentor.`;
return [{ json: { reply, leave_type: d.leave_type || null } }];
